sys_script_include.script:
var LOAEvaluationVersionService = Class.create();
LOAEvaluationVersionService.prototype = {
    initialize: function() {
        this.TABLE = 'x_gegis_ins_policy_loa_evaluation';
        this.LINE_TABLE = 'x_gegis_ins_policy_submission_line';

        // loa_evaluation.evaluation_trigger is ITS OWN pre-existing local choice
        // (initial_evaluation/grant_change/manual_reevaluation/exposure_change/
        // quote_change/intake_change) - a different, older taxonomy than the new
        // x_gegis_ins_policy_uw_trigger_reason.code catalog UWTriggerReasonResolver
        // resolves against. The constraints forbid touching existing fields/choices,
        // so rather than adding a trigger_reason reference column to this table,
        // this map translates the shared code onto the closest existing
        // evaluation_trigger value. ASSUMPTION, documented here as the single place
        // it happens: initial_assignment/underwriter_reassigned/manual_correction
        // have no exact equivalent in the old list, so they map to the nearest
        // fit (initial_evaluation / manual_reevaluation / manual_reevaluation).
        var C = x_gegis_ins_policy.Constants.CHOICE.UW_TRIGGER_REASON_CODE;
        var map = {};
        map[C.INITIAL_SUBMISSION]     = 'initial_evaluation';
        map[C.TIV_CHANGE]             = 'exposure_change';
        map[C.PROPERTY_COUNT_CHANGE]  = 'exposure_change';
        map[C.RENEWAL]                = 'intake_change';
        map[C.ENDORSEMENT]            = 'intake_change';
        map[C.INITIAL_ASSIGNMENT]     = 'initial_evaluation';
        map[C.UNDERWRITER_REASSIGNED] = 'manual_reevaluation';
        map[C.MANUAL_CORRECTION]      = 'manual_reevaluation';
        this.CODE_TO_EVALUATION_TRIGGER = map;
    },

    /**
     * Create the next loa_evaluation header row for a submission_line.
     *
     *   1. Look up the current active=true row for this submission_line (there
     *      is at most one) to get its version number and evaluation_status.
     *   2. Insert version = (that version + 1), or 1 if none exists yet, with
     *      active = true.
     *   3. Flip the previous active row to false, in the SAME call.
     *
     * Result columns (authority_tier, is_authorized, checks_count, breach_count,
     * decision, decided_by/on, ...) are intentionally left untouched - HOOK POINT
     * for the future evaluation flow, which reads the row this method just
     * created (active=true for the submission_line) and populates them.
     *
     * @param submissionLineId sys_id of x_gegis_ins_policy_submission_line (required)
     * @param triggerReasonId sys_id of x_gegis_ins_policy_uw_trigger_reason,
     *        e.g. from UWTriggerReasonResolver.resolve() (required)
     * @return sys_id of the newly inserted row, or '' when the call was refused
     */
    createNextVersion: function(submissionLineId, triggerReasonId) {
        if (!submissionLineId || !triggerReasonId) {
            gs.error('[LOAEvaluationVersionService] createNextVersion refused - submissionLineId=' +
                submissionLineId + ' triggerReasonId=' + triggerReasonId +
                ' (both are required; a header row with a null/broken trigger_reason is not created)');
            return '';
        }

        var line = new GlideRecord(this.LINE_TABLE);
        if (!line.get(submissionLineId)) {
            gs.error('[LOAEvaluationVersionService] submission_line ' + submissionLineId + ' not found');
            return '';
        }

        var reason = new GlideRecord('x_gegis_ins_policy_uw_trigger_reason');
        if (!reason.get(triggerReasonId)) {
            gs.error('[LOAEvaluationVersionService] uw_trigger_reason ' + triggerReasonId + ' not found');
            return '';
        }
        var evaluationTrigger = this.CODE_TO_EVALUATION_TRIGGER[String(reason.getValue('code'))];
        if (!evaluationTrigger) {
            gs.error('[LOAEvaluationVersionService] no evaluation_trigger mapping for code=' +
                reason.getValue('code') + ' - defaulting to manual_reevaluation, update the map');
            evaluationTrigger = 'manual_reevaluation';
        }

        var nextVersion = 1;
        var previousStatus = '';
        var prev = new GlideRecord(this.TABLE);
        prev.addQuery('submission_line', submissionLineId);
        prev.addQuery('active', true);
        prev.query();
        if (prev.next()) {
            nextVersion = (parseInt(prev.getValue('version'), 10) || 1) + 1;
            previousStatus = String(prev.getValue('evaluation_status'));
            prev.setValue('active', false);
            prev.update();
        }

        var gr = new GlideRecord(this.TABLE);
        gr.initialize();
        gr.setValue('submission', line.getValue('submission'));
        gr.setValue('submission_line', submissionLineId);
        gr.setValue('line_of_business', line.getValue('line_of_business'));
        gr.setValue('version', nextVersion);
        gr.setValue('active', true);
        gr.setValue('evaluation_trigger', evaluationTrigger);
        gr.setValue('evaluated_on', new GlideDateTime());
        if (previousStatus)
            gr.setValue('previous_evaluation_status', previousStatus);
        // evaluation_status keeps its dictionary default ('pending'). authority_tier,
        // is_authorized, checks_count, breach_count, decision*, decided_by/on: HOOK
        // POINT for the future evaluation flow. Left untouched here on purpose.

        var newId = gr.insert();
        if (!newId) {
            gs.error('[LOAEvaluationVersionService] insert REFUSED for submission_line=' +
                submissionLineId + ' v' + nextVersion + ' trigger_reason=' + triggerReasonId +
                ' - check ACLs/mandatory fields on ' + this.TABLE);
            return '';
        }
        return newId;
    },

    type: 'LOAEvaluationVersionService'
};
